<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Untitled Document</title>
    <style>
        @import url('https://fonts.googleapis.com/css2?family=Georgia:wght@400;600&amp;family=Times+New+Roman:wght@400;700&amp;display=swap');

        body {
            font-family: 'Georgia', serif;
            margin: 40px auto;
            max-width: 900px;
            line-height: 1.4;
            background: #fff;
            color: #000;
            position: relative;
        }

        .page {
            page-break-after: always;
            margin-bottom: 30px;
            min-height: 1200px;
            position: relative;
        }

        .header {
            text-align: center;
            font-size: 24px;
            font-weight: 600;
            margin-bottom: 20px;
            border-bottom: 2px solid #000;
            padding-bottom: 10px;
        }

        .column {
            display: flex;
            gap: 40px;
            margin-bottom: 40px;
        }

        .col-left {
            width: 48%;
            font-size: 14px;
        }

        .col-right {
            width: 48%;
            font-size: 14px;
        }

        .text-block {
            margin-bottom: 15px;
        }

        .bold {
            font-weight: 700;
        }

        .placeholder {
            width: 100%;
            height: 120px;
            border: 1px solid #000;
            background: #f8f8f8;
            margin: 20px 0;
            display: flex;
            align-items: center;
            justify-content: center;
            font-style: italic;
            color: #555;
            text-align: center;
            position: relative;
        }

        .placeholder::after {
            content: "Placeholder";
            font-size: 12px;
        }

        .footer {
            text-align: center;
            font-size: 11px;
            margin-top: 40px;
            border-top: 1px solid #000;
            padding-top: 10px;
        }
    </style>
</head>
<body>
    <div class="page">
        <div class="header">Document Title</div>

        <div class="column">
            <div class="col-left">
                <div class="text-block">
                    <span class="bold">This is the left column.</span><br>
                    Content appears here exactly as in the original layout.
                </div>
                <div class="text-block">
                    Line 2 – continues in the same column.
                </div>
                <div class="text-block">
                    <span class="bold">Bold text example.</span>
                </div>
            </div>
            <div class="col-right">
                <div class="text-block">
                    <span class="bold">This is the right column.</span><br>
                    Content appears here exactly as in the original layout.
                </div>
                <div class="text-block">
                    Line 2 – continues in the same column.
                </div>
                <div class="text-block">
                    <span class="bold">Bold text example.</span>
                </div>
            </div>
        </div>

        <div class="placeholder" style="margin: 30px 0; height: 150px;">
            [Chart / Diagram: top center]
        </div>

        <div class="column">
            <div class="col-left">
                <div class="text-block">
                    Additional content in the left column below the placeholder.
                </div>
            </div>
            <div class="col-right">
                <div class="text-block">
                    Additional content in the right column below the placeholder.
                </div>
            </div>
        </div>

        <div class="placeholder" style="margin: 30px 0; height: 100px;">
            [Signature / Photo: bottom left]
        </div>

        <div class="text-block">
            <span class="bold">End of document content.</span>
        </div>
    </div>

    <div class="footer">
        Footer text or page number goes here.
    </div>
</body>
</html>
